{"findings":[{"tipo":"CPU","causa_raiz":"O método Update executa repetidamente GameObject.FindObjectsOfType<GameObject>(), varrendo linearmente toda a hierarquia de objetos da cena a cada iteração, além de realizar concatenações acumulativas de string ('s += i.ToString()') e alocações de grandes arrays na memória gerenciada a cada frame, gerando picos massivos de processamento e coletas frequentes do Garbage Collector (GC de ~7.7 MB e pausas de 11.36 ms).","codigo_refatorado":"using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private readonly List<GameObject> trackedObjects = new List<GameObject>();
        private readonly StringBuilder sharedStringBuilder = new StringBuilder(2048);
        private MaterialPropertyBlock propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var empty = new GameObject("Empty_" + i);
                trackedObjects.Add(empty);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                sharedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    sharedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int count = trackedObjects.Count;
                    for (int i = 0; i < count; i++)
                    {
                        var obj = trackedObjects[i];
                        if (obj != null)
                        {
                            _ = obj.activeInHierarchy;
                        }
                    }
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            trackedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(propertyBlock);
                    propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(propertyBlock);
                }
            }
        }
    }
}","explicacao_didatica":"Imagine que a cada frame seu jogo tenta ler uma lista telefônica inteira (FindObjectsOfType) para encontrar pessoas, além de rasgar e jogar folhas de papel no chão toda vez que junta palavras (concatenação de string com '+'). O Unity precisa pausar o jogo para o 'lixeiro' (Garbage Collector) recolher essas folhas, gerando travamentos perceptíveis. Para corrigir isso: 1) Mantemos uma lista em memória das coisas criadas em vez de vasculhar a cena inteira; 2) Usamos StringBuilder para reaproveitar o mesmo espaço de texto; 3) Usamos MaterialPropertyBlock para mudar cores sem duplicar materiais na memória de vídeo."}],"dicas_level_design":null}

